import { useEffect, useRef } from 'react';
import { ExternalLink, X } from 'lucide-react';
import type { PodcastChannel, PodcastVideo } from './catalog';

export default function PodcastPlayer({
  video,
  channel,
  onClose,
}: {
  video: PodcastVideo;
  channel: PodcastChannel;
  onClose: () => void;
}) {
  const dialogRef = useRef<HTMLDialogElement>(null);

  useEffect(() => {
    const dialog = dialogRef.current;
    dialog?.showModal();
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      dialog?.close();
      document.body.style.overflow = previousOverflow;
    };
  }, []);

  return (
    <dialog
      ref={dialogRef}
      aria-labelledby="podcast-player-title"
      onCancel={(event) => {
        event.preventDefault();
        onClose();
      }}
      onClick={(event) => {
        if (event.target === event.currentTarget) onClose();
      }}
      className="fixed inset-0 m-auto max-h-[90dvh] w-[calc(100%-2rem)] max-w-lg overflow-y-auto rounded-2xl border-0 bg-white p-0 text-gray-900 shadow-2xl backdrop:bg-black/70 backdrop:backdrop-blur-sm dark:bg-neutral-900 dark:text-white"
    >
      <div className="flex items-center gap-3 px-4 py-2">
        <p className="flex-1 text-sm font-semibold">{channel.name}</p>
        <button
          type="button"
          autoFocus
          onClick={onClose}
          aria-label="Đóng video"
          className="flex h-11 w-11 items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-neutral-800"
        >
          <X size={21} />
        </button>
      </div>
      <iframe
        key={video.id}
        title={video.title}
        src={`https://www.youtube.com/embed/${video.id}?autoplay=1&rel=0&playsinline=1&origin=${encodeURIComponent(window.location.origin)}`}
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
        allowFullScreen
        referrerPolicy="strict-origin-when-cross-origin"
        className="aspect-video w-full border-0 bg-black"
      />
      <div className="p-4">
        <h2 id="podcast-player-title" className="text-base font-bold leading-6">
          {video.title}
        </h2>
        <p className="mt-3 text-xs leading-5 text-gray-500 dark:text-neutral-400">
          Nếu video không phát được tại đây, bạn có thể mở trực tiếp trên
          YouTube.
        </p>
        <a
          href={`https://www.youtube.com/watch?v=${video.id}`}
          target="_blank"
          rel="noreferrer"
          className="mt-3 inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary/10 px-4 text-sm font-semibold text-primary dark:text-indigo-300"
        >
          Mở trên YouTube <ExternalLink size={15} />
        </a>
      </div>
    </dialog>
  );
}
